DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_audit_logs` ()   BEGIN
    DELETE FROM log_audit_sistem;
    ALTER TABLE log_audit_sistem AUTO_INCREMENT = 1;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_finalisasi_rab` (IN `p_usulan_id` INT, IN `p_user_id` INT)   BEGIN
    DECLARE v_grand_total DECIMAL(18,2);

    -- Hitung pakai Function
    SET v_grand_total = fn_hitung_total_rab(p_usulan_id);

    -- Update tabel utama
    UPDATE usulan_kegiatan
    SET nominal_pencairan = v_grand_total, updated_at = NOW()
    WHERE id = p_usulan_id;

    -- Log aktivitas
    INSERT INTO log_audit_sistem (user_id, aksi, ip_address, timestamp)
    VALUES (p_user_id, CONCAT('FINALIZE_RAB - Total: ', v_grand_total), 'SYSTEM', NOW());
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_laporan_rab_kategori` (IN `p_usulan_id` INT)   BEGIN
    SELECT 
        k.nama_kategori,
        fn_hitung_rab_per_kategori(p_usulan_id, k.id) as total_kategori,
        COUNT(r.id) as jumlah_item
    FROM master_kategori_anggaran k
    LEFT JOIN rab_detail r ON r.kategori_id = k.id AND r.usulan_id = p_usulan_id
    GROUP BY k.id, k.nama_kategori
    ORDER BY k.id;
    
    -- Total keseluruhan
    SELECT fn_hitung_total_rab(p_usulan_id) as grand_total;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ubah_status_usulan` (IN `p_usulan_id` INT, IN `p_user_id` INT, IN `p_status_baru` VARCHAR(50), IN `p_catatan` TEXT)   BEGIN
    DECLARE v_status_lama VARCHAR(50);
    
    -- Ambil status lama
    SELECT status_terkini INTO v_status_lama 
    FROM usulan_kegiatan WHERE id = p_usulan_id;
    
    -- Update Status
    UPDATE usulan_kegiatan 
    SET status_terkini = p_status_baru, updated_at = NOW() 
    WHERE id = p_usulan_id;
    
    -- Catat Log
    INSERT INTO log_histori_usulan (usulan_id, user_id, status_lama, status_baru, catatan, timestamp)
    VALUES (p_usulan_id, p_user_id, v_status_lama, p_status_baru, p_catatan, NOW());
END$$

--
-- Functions
--
CREATE DEFINER=`root`@`localhost` FUNCTION `fn_hitung_keterlambatan_lpj` (`p_usulan_id` INT) RETURNS INT(11) DETERMINISTIC READS SQL DATA BEGIN
    DECLARE batas_lpj DATETIME;
    DECLARE selisih INT;
    DECLARE tanggal_pencairan_pertama DATETIME;

    -- Ambil tanggal pencairan pertama untuk usulan ini
    SELECT pc.tanggal_pencairan INTO tanggal_pencairan_pertama
    FROM pencairan_dana pc
    JOIN pengajuan_kegiatan p ON pc.pengajuan_id = p.id
    WHERE p.usulan_id = p_usulan_id
    ORDER BY pc.tanggal_pencairan ASC
    LIMIT 1;

    IF tanggal_pencairan_pertama IS NULL THEN
        RETURN 0;
    END IF;

    -- Batas LPJ adalah 14 hari setelah pencairan pertama
    SET batas_lpj = DATE_ADD(tanggal_pencairan_pertama, INTERVAL 14 DAY);

    SET selisih = DATEDIFF(NOW(), batas_lpj);

    RETURN IF(selisih > 0, selisih, 0);
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_hitung_rab_per_kategori` (`p_usulan_id` INT, `p_kategori_id` INT) RETURNS DECIMAL(18,2) DETERMINISTIC READS SQL DATA BEGIN
    DECLARE total DECIMAL(18,2);
    
    SELECT COALESCE(SUM(total), 0) INTO total
    FROM rab_detail
    WHERE usulan_id = p_usulan_id 
    AND kategori_id = p_kategori_id;
    
    RETURN total;
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_hitung_total_rab` (`p_usulan_id` INT) RETURNS DECIMAL(18,2) DETERMINISTIC READS SQL DATA BEGIN
    DECLARE v_total DECIMAL(18,2);
    SELECT COALESCE(SUM(total), 0) INTO v_total 
    FROM rab_detail WHERE usulan_id = p_usulan_id;
    RETURN v_total;
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_validasi_bobot_indikator` (`p_usulan_id` INT) RETURNS TINYINT(1) DETERMINISTIC READS SQL DATA BEGIN
    DECLARE total_bobot DECIMAL(5,2);
    
    -- Karena Indikator Kinerja disimpan di JSON, fungsi ini tidak relevan lagi atau perlu disesuaikan.
    -- Kita anggap validasi bobot Indikator dilakukan di sisi aplikasi.
    RETURN 1; 
END$$

