--
-- Table structure for table `pengajuan_kegiatan`
--

CREATE TABLE `pengajuan_kegiatan` (
  `id` int(11) NOT NULL,
  `usulan_id` int(11) NOT NULL,
  `penanggung_jawab` varchar(255) NOT NULL,
  `pelaksana_kegiatan` text NOT NULL,
  `tanggal_mulai` date NOT NULL,
  `tanggal_selesai` date NOT NULL,
  `surat_pengantar_path` varchar(255) DEFAULT NULL,
  `status_ppk` enum('Menunggu','Disetujui') DEFAULT 'Menunggu',
  `tgl_status_ppk` datetime DEFAULT NULL,
  `status_wd2` enum('Menunggu','Disetujui') DEFAULT 'Menunggu',
  `tgl_status_wd2` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `rekomendasi_ppk` text DEFAULT NULL,
  `rekomendasi_wd2` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

