--
-- Table structure for table `rab_detail`
--

CREATE TABLE `rab_detail` (
  `id` int(11) NOT NULL,
  `usulan_id` int(11) NOT NULL,
  `kategori_id` int(11) NOT NULL,
  `deskripsi` varchar(255) NOT NULL,
  `volume_factor_1` decimal(18,2) DEFAULT 0.00,
  `satuan_factor_1_id` int(11) DEFAULT NULL,
  `satuan_factor_1_custom` varchar(100) DEFAULT NULL,
  `volume_factor_2` decimal(18,2) DEFAULT 0.00,
  `satuan_factor_2_id` int(11) DEFAULT NULL,
  `satuan_factor_2_custom` varchar(100) DEFAULT NULL,
  `volume` decimal(18,2) NOT NULL COMMENT 'Volume Total (V1 * V2)',
  `satuan_id` int(11) DEFAULT NULL,
  `satuan_custom` varchar(100) DEFAULT NULL,
  `harga_satuan` decimal(18,2) NOT NULL,
  `total` decimal(18,2) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

