--
-- Triggers `rab_detail`
--
DELIMITER $$
CREATE TRIGGER `trg_validasi_input_rab` BEFORE INSERT ON `rab_detail` FOR EACH ROW BEGIN
    -- Validasi volume_factor_1 tidak boleh negatif
    IF NEW.volume_factor_1 < 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Volume Factor 1 tidak boleh negatif';
    END IF;
    
    -- Validasi volume_factor_2 tidak boleh negatif  
    IF NEW.volume_factor_2 < 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Volume Factor 2 tidak boleh negatif';
    END IF;
    
    -- Validasi volume total tidak boleh negatif
    IF NEW.volume < 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Volume total tidak boleh negatif';
    END IF;
    
    -- Validasi harga_satuan tidak boleh negatif
    IF NEW.harga_satuan < 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Harga satuan tidak boleh negatif';
    END IF;
    
    -- Validasi total tidak boleh negatif
    IF NEW.total < 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Total RAB tidak boleh negatif';
    END IF;
END
$$
DELIMITER ;
