--
-- Triggers `usulan_kegiatan`
--
DELIMITER $$
CREATE TRIGGER `trg_after_update_status` AFTER UPDATE ON `usulan_kegiatan` FOR EACH ROW BEGIN
    -- Log perubahan status
    IF OLD.status_terkini != NEW.status_terkini THEN
        INSERT INTO log_audit_sistem (user_id, aksi, ip_address, timestamp)
        VALUES (
            COALESCE(@current_user_id, 0),
            CONCAT('STATUS_CHANGE: ', OLD.status_terkini, ' → ', NEW.status_terkini, ' (ID: ', NEW.id, ')'),
            'TRIGGER',
            NOW()
        );
    END IF;
END
$$
DELIMITER ;

-- --------------------------------------------------------

--
-- Stand-in structure for view `v_lpj_keterlambatan`
-- (See below for the actual view)
--
CREATE TABLE `v_lpj_keterlambatan` (
`lpj_id` int(11)
,`usulan_id` int(11)
,`judul_usulan` varchar(255)
,`tanggal_pengajuan` timestamp
,`tanggal_deadline` date
,`status_lpj` enum('Belum Upload','Diajukan','Revisi','Disetujui')
);

-- --------------------------------------------------------

--
-- Structure for view `v_lpj_keterlambatan`
--
DROP TABLE IF EXISTS `v_lpj_keterlambatan`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_lpj_keterlambatan`  AS SELECT `l`.`id` AS `lpj_id`, `u`.`id` AS `usulan_id`, `u`.`nama_kegiatan` AS `judul_usulan`, `p`.`created_at` AS `tanggal_pengajuan`, `pc`.`tanggal_batas_lpj` AS `tanggal_deadline`, `l`.`status_terkini` AS `status_lpj` FROM (((`lpj` `l` join `pencairan_dana` `pc` on(`l`.`pencairan_id` = `pc`.`id`)) join `pengajuan_kegiatan` `p` on(`pc`.`pengajuan_id` = `p`.`id`)) join `usulan_kegiatan` `u` on(`p`.`usulan_id` = `u`.`id`)) ;

